import { loadFont as loadPoppins } from "@remotion/google-fonts/Poppins";
import React from "react";
import { V2_DUR, WARP_V2 } from "./warpV2";
import { AbsoluteFill, Easing, Img, OffthreadVideo, Sequence, interpolate, spring, staticFile, useCurrentFrame } from "remotion";

// CLICKMÁGICO · Espaço Conforto Mágico (cadeiras de massagem para eventos). Pedido do Gustavo ONNU, 16/10/2026.
// Locução = texto do cliente, voz o locutor ((arquivo do cliente)). Tempos = palavra na voz
// ((arquivo do cliente)); a voz entra em LEAD.
// Pouco material (arte + 4 takes de IA) → motion, intercalando telas só de texto/motion com pedaços dos takes (pedido do cliente).
// Identidade da arte: creme, roxo profundo, degradê roxo → magenta → laranja, Poppins pesada, logo com o "o" de sol.

const { fontFamily: PP } = loadPoppins("normal", { weights: ["500", "600", "700", "800"], subsets: ["latin", "latin-ext"] });

export const GO_FPS = 30;
const LEAD = 0.1;
export const GO_FRAMES = Math.round(33.8 * GO_FPS);
export const GO2_FRAMES = Math.round(V2_DUR * GO_FPS);

// v2: voz mais animada e sem pausas longas. A cena continua escrita no tempo da v1; a tabela converte o tempo novo no antigo.
type Warp = [number, number][];
const interp = (v: number, xs: number[], ys: number[]) => interpolate(v, xs, ys, { extrapolateLeft: "extend", extrapolateRight: "extend" });
const WarpCtx = React.createContext<Warp | null>(null);

const CREAM = "#FFF9F3";
const INK = "#24065A";
const PURPLE = "#9B0FA8";
const MAG = "#FF0A78";
const ORANGE = "#FF7A2E";
const GRAD = `linear-gradient(100deg, ${PURPLE} 0%, ${MAG} 55%, ${ORANGE} 100%)`;

const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const OUT = Easing.bezier(0.16, 1, 0.3, 1);
const k = (t: number, a: number, d: number) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: OUT });
const lin = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], cl);
const sp = (t: number, a: number, damping = 14, stiffness = 180) =>
  spring({ frame: Math.round((t - a) * GO_FPS), fps: GO_FPS, config: { damping, stiffness } });
const src = (f: string) => staticFile(`gustavo-onnu/${f}`);

// ───────── texto ─────────
type W = [string, number];
const Words: React.FC<{ t: number; words: W[]; size?: number; color?: string; weight?: number; grad?: boolean }> = ({ t, words, size = 64, color = INK, weight = 700, grad }) => (
  <div style={{ fontFamily: PP, fontWeight: weight, fontSize: size, lineHeight: 1.12, color, textAlign: "center", whiteSpace: "nowrap", letterSpacing: "-0.01em" }}>
    {words.map(([w, at], i) => {
      const q = k(t, at, 0.24);
      return (
        <span key={i} style={{ display: "inline-block", margin: "0 0.12em", opacity: q, transform: `translateY(${(1 - q) * 22}px) scale(${0.65 + 0.35 * q})`,
          ...(grad ? { backgroundImage: GRAD, WebkitBackgroundClip: "text", backgroundClip: "text", color: "transparent", padding: "0 0.04em 0.08em" } : {}) }}>{w}</span>
      );
    })}
  </div>
);
// palavra grande que chega com impulso e assenta
const Title: React.FC<{ t: number; at: number; children: React.ReactNode; size?: number; color?: string; grad?: boolean }> = ({ t, at, children, size = 150, color = INK, grad }) => {
  const s = sp(t, at, 13, 220);
  return (
    <div style={{ fontFamily: PP, fontWeight: 800, fontSize: size, lineHeight: 1.02, letterSpacing: "-0.03em", textAlign: "center", whiteSpace: "nowrap", color,
      opacity: Math.min(1, s * 3), transform: `scale(${1.45 - 0.45 * s})`,
      ...(grad ? { backgroundImage: GRAD, WebkitBackgroundClip: "text", backgroundClip: "text", color: "transparent", padding: "0 0.05em 0.1em" } : {}) }}>{children}</div>
  );
};
const Block: React.FC<{ t: number; top: number; at: number; out?: number; gap?: number; children: React.ReactNode }> = ({ t, top, at, out, gap = 10, children }) => {
  if (t < at - 0.05 || (out !== undefined && t > out + 0.14)) return null;
  const o = out === undefined ? 0 : k(t, out, 0.12);
  return (
    <div style={{ position: "absolute", left: 120, right: 120, top, display: "flex", flexDirection: "column", alignItems: "center", gap, opacity: 1 - o, transform: `scale(${1 - o * 0.08})` }}>{children}</div>
  );
};

// lettering das cenas de take: bloco no degradê da marca, embaixo, sempre no mesmo lugar
const Band: React.FC<{ t: number; at: number; out?: number; top?: number; children: React.ReactNode }> = ({ t, at, out, top = 1360, children }) => {
  if (t < at - 0.05 || (out !== undefined && t > out + 0.14)) return null;
  const s = sp(t, at, 15, 200);
  const o = out === undefined ? 0 : k(t, out, 0.12);
  return (
    <div style={{ position: "absolute", left: 100, right: 100, top, display: "flex", justifyContent: "center", opacity: Math.min(1, s * 3) * (1 - o) }}>
      <div style={{ background: GRAD, borderRadius: 44, padding: "30px 54px 38px", boxShadow: "0 30px 80px rgba(36,6,90,0.45)", display: "flex", flexDirection: "column", alignItems: "center", gap: 2,
        transform: `translateY(${(1 - s) * 120}px) scale(${(0.8 + 0.2 * s) * (1 - o * 0.06)})` }}>{children}</div>
    </div>
  );
};

// ───────── cena e transições ─────────
type Tr = "none" | "slideL" | "slideUp" | "circle" | "wipe" | "zoom" | "iris" | "band";
const TD = 0.38;
const Scene: React.FC<{ t: number; a: number; b: number; tr: Tr; bg: string; cam?: [number, number]; drift?: number; children: React.ReactNode }> = ({ t, a, b, tr, bg, cam = [1, 1.06], drift = -30, children }) => {
  if (t < a || t > b + TD) return null;
  const q = tr === "none" ? 1 : k(t, a, TD);
  let clip = "none", tf = "", op = 1;
  if (tr === "band") clip = `polygon(0 ${(1 - q) * 100}%, 100% ${(1 - q) * 100 - 20 * (1 - q)}%, 100% 100%, 0 100%)`;
  if (tr === "wipe") clip = `polygon(0 0, ${q * 125}% 0, ${q * 125 - 25}% 100%, 0 100%)`;
  if (tr === "slideL") tf = `translateX(${(1 - q) * 100}%)`;
  if (tr === "slideUp") tf = `translateY(${(1 - q) * 100}%)`;
  if (tr === "zoom") { tf = `scale(${1.3 - 0.3 * q})`; op = Math.min(1, q * 1.7); }
  if (tr === "circle") clip = `circle(${q * 120}% at 50% 50%)`;
  if (tr === "iris") clip = `inset(${(1 - q) * 50}% ${(1 - q) * 50}% round ${(1 - q) * 200}px)`;
  const p = lin(t, a, b + TD);
  const z = Math.max(cam[0] + (cam[1] - cam[0]) * p, 1.006 + (Math.abs(drift * p) * 2) / 1920);
  return (
    <AbsoluteFill style={{ clipPath: clip, transform: tf || undefined, opacity: op, overflow: "hidden", background: bg }}>
      <AbsoluteFill style={{ transform: `translateY(${(drift * p).toFixed(1)}px) scale(${z.toFixed(4)})` }}>{children}</AbsoluteFill>
    </AbsoluteFill>
  );
};

// pedaço de take ocupando o quadro inteiro, com aproximação lenta e sombra embaixo para o lettering
const Take: React.FC<{ a: number; b: number; file: string; from: number; t: number; z?: [number, number]; x?: [number, number]; veil?: number }> = ({ a, b, file, from, t, z = [1.04, 1.16], x = [0, 0], veil = 0 }) => {
  const warp = React.useContext(WarpCtx);
  const toNew = (v: number) => (warp ? interp(v, warp.map((w) => w[1]), warp.map((w) => w[0])) : v);
  const p = lin(t, a, b + TD);
  return (
    <>
      <Sequence from={Math.round((toNew(a) + LEAD) * GO_FPS)} durationInFrames={Math.round((toNew(b) - toNew(a) + TD + 0.2) * GO_FPS)} layout="none">
        <AbsoluteFill style={{ transform: `translateX(${x[0] + (x[1] - x[0]) * p}px) scale(${z[0] + (z[1] - z[0]) * p})` }}>
          <OffthreadVideo src={src(file)} startFrom={Math.round(from * GO_FPS)} muted style={{ width: "100%", height: "100%", objectFit: "cover" }} />
        </AbsoluteFill>
      </Sequence>
      <AbsoluteFill style={{ background: "linear-gradient(180deg, rgba(36,6,90,0) 52%, rgba(36,6,90,0.55) 100%)" }} />
      {veil > 0 && <AbsoluteFill style={{ background: GRAD, opacity: veil }} />}
    </>
  );
};

// ───────── peças ─────────
const Logo: React.FC<{ t: number; at: number; w: number; top: number; white?: boolean }> = ({ t, at, w, top, white }) => {
  const s = sp(t, at, 12, 190);
  return (
    <Img src={src(white ? "logo-branco.png" : "logo.png")} style={{ position: "absolute", left: (1080 - w) / 2, top, width: w, height: w * 0.46, opacity: Math.min(1, s * 3),
      transform: `scale(${0.3 + 0.7 * s}) rotate(${(1 - s) * -12}deg)` }} />
  );
};

// brilho de quatro pontas: aparece uma vez e some (o "mágico")
const Spark: React.FC<{ t: number; at: number; x: number; y: number; size: number; color?: string }> = ({ t, at, x, y, size, color = ORANGE }) => {
  const q = lin(t, at, at + 0.7);
  if (q <= 0 || q >= 1) return null;
  const s = Math.sin(q * Math.PI);
  return (
    <svg width={size} height={size} viewBox="0 0 100 100" style={{ position: "absolute", left: x - size / 2, top: y - size / 2, transform: `scale(${s}) rotate(${q * 90}deg)`, opacity: s }}>
      <path d="M50 0 C54 36 64 46 100 50 C64 54 54 64 50 100 C46 64 36 54 0 50 C36 46 46 36 50 0 Z" fill={color} />
    </svg>
  );
};

// formas da arte (círculo e arco em degradê) entrando pelos cantos
const Shapes: React.FC<{ t: number; at: number }> = ({ t, at }) => {
  const s1 = k(t, at, 0.9), s2 = k(t, at + 0.15, 0.9), g = lin(t, at, at + 2.2);
  return (
    <>
      <div style={{ position: "absolute", right: -160 + (1 - s1) * -400 + g * 60, top: 120 - (1 - s1) * 300 + g * 140, width: 420, height: 420, borderRadius: 210,
        background: `linear-gradient(140deg, ${MAG}, ${ORANGE})`, opacity: 0.95, transform: `rotate(${s1 * 30 + g * 40}deg) scale(${1 + g * 0.15})` }} />
      <div style={{ position: "absolute", left: -220 - (1 - s2) * 400, bottom: 120 - (1 - s2) * 300, width: 480, height: 480, borderRadius: 240,
        border: `70px solid ${ORANGE}`, borderRightColor: "transparent", borderBottomColor: "transparent", transform: `rotate(${-20 + s2 * 40 + g * 50}deg)` }} />
    </>
  );
};

const Circle: React.FC<{ t: number; at: number; size: number; children: React.ReactNode; dark?: boolean }> = ({ t, at, size, children, dark }) => {
  const s = sp(t, at, 11, 220);
  return (
    <div style={{ width: size, height: size, borderRadius: size / 2, background: dark ? "rgba(255,255,255,0.1)" : GRAD, display: "flex", alignItems: "center", justifyContent: "center",
      boxShadow: dark ? "none" : "0 30px 70px rgba(255,10,120,0.35)", border: dark ? "6px solid rgba(255,255,255,0.9)" : "none",
      opacity: Math.min(1, s * 3), transform: `scale(${s}) rotate(${(1 - s) * -20}deg)`, flex: "none" }}>{children}</div>
  );
};

