// item da lista de eventos: ícone + palavra, um por vez no mesmo lugar
const Item: React.FC<{ t: number; at: number; out?: number; icon: React.ReactNode; word: string; size: number; sub?: W }> = ({ t, at, out, icon, word, size, sub }) => {
  if (t < at - 0.05 || (out !== undefined && t > out + 0.12)) return null;
  const o = out === undefined ? 0 : k(t, out, 0.1);
  return (
    <div style={{ position: "absolute", left: 120, right: 120, top: 640, display: "flex", flexDirection: "column", alignItems: "center", gap: 70, opacity: 1 - o, transform: `scale(${1 - 0.1 * o})` }}>
