export const ConfortoMagicoV2: React.FC = () => (
  <WarpCtx.Provider value={WARP_V2}>
    <ConfortoMagico />
  </WarpCtx.Provider>
);

export const ConfortoMagico: React.FC = () => {
  const frame = useCurrentFrame();
  const warp = React.useContext(WarpCtx);
  const tn = frame / GO_FPS - LEAD;
  const t = warp ? interp(tn, warp.map((w) => w[0]), warp.map((w) => w[1])) : tn;
  return (
    <AbsoluteFill style={{ background: CREAM, overflow: "hidden" }}>
      {/* 1 · Chegou uma novidade que seu público… */}
      <Scene t={t} a={-LEAD} b={1.95} tr="none" bg={CREAM} cam={[1.0, 1.2]} drift={-50}>
        <Shapes t={t} at={-0.1} />
        <Block t={t} top={680} at={-0.1} gap={18}>
          {(() => {
            const s = sp(t, -0.05, 10, 260);
            return <div style={{ fontFamily: PP, fontWeight: 700, fontSize: 40, letterSpacing: "0.18em", color: "#fff", background: MAG, padding: "12px 40px 14px", borderRadius: 40,
              opacity: Math.min(1, s * 3), transform: `scale(${2 - s}) rotate(${(1 - s) * -8}deg)` }}>NOVO PRODUTO</div>;
          })()}
          <Words t={t} size={92} weight={800} words={[["Chegou", 0.05], ["uma", 0.31]]} />
          <Title t={t} at={0.41} size={190} grad>novidade</Title>
          <div style={{ height: 20 }} />
          <Words t={t} size={64} weight={600} color={PURPLE} words={[["que", 0.95], ["seu", 1.07], ["público", 1.29], ["vai…", 1.77]]} />
        </Block>
        <Spark t={t} at={0.55} x={930} y={880} size={110} />
        <Spark t={t} at={0.8} x={150} y={1120} size={80} color={MAG} />
      </Scene>

      {/* 2 · …adorar sentir! (take: mulher relaxando) */}
      <Scene t={t} a={1.95} b={3.9} tr="circle" bg={INK} cam={[1, 1]} drift={0}>
        <Take t={t} a={1.95} b={3.9} file="take-woman.mp4" from={3.2} z={[1.08, 1.2]} />
        <Band t={t} at={2.0}>
          <Words t={t} size={120} weight={800} color="#fff" words={[["adorar", 1.99]]} />
          <Words t={t} size={120} weight={800} color="#fff" words={[["sentir!", 2.61]]} />
        </Band>
      </Scene>

      {/* 3 · A ClickMágico apresenta o Espaço Conforto Mágico */}
      <Scene t={t} a={3.9} b={7.95} tr="slideUp" bg={CREAM} cam={[1, 1.07]} drift={-30}>
        <Logo t={t} at={3.99} w={560} top={190} />
        <Block t={t} top={490} at={4.65} gap={0}>
          <Words t={t} size={56} weight={600} color={PURPLE} words={[["apresenta", 4.65], ["o", 5.59]]} />
          <Words t={t} size={92} weight={800} words={[["Espaço", 5.69]]} />
          <Title t={t} at={6.39} size={164} grad>Conforto</Title>
          <Title t={t} at={7.11} size={164} grad>Mágico</Title>
        </Block>
        {(() => {
          const s = sp(t, 5.69, 15, 160);
          return (
            <div style={{ position: "absolute", left: 120, width: 840, top: 1160, height: 840 / 2.053, borderRadius: 48, overflow: "hidden", boxShadow: "0 40px 90px rgba(36,6,90,0.3)",
              opacity: Math.min(1, s * 3), transform: `translateY(${(1 - s) * 700}px) rotate(${(1 - s) * 8}deg)` }}>
              <Img src={src("arte-foto.jpg")} style={{ width: "100%", height: "100%", objectFit: "cover", transform: `scale(${1.15 - 0.12 * lin(t, 5.7, 8.2)})` }} />
            </div>
          );
        })()}
        <Spark t={t} at={7.15} x={900} y={1000} size={120} />
        <Spark t={t} at={7.3} x={170} y={860} size={84} color={MAG} />
      </Scene>

      {/* 4 · Cadeiras de massagem automáticas que atraem o público (take: estande) */}
      <Scene t={t} a={7.95} b={11.6} tr="wipe" bg={INK} cam={[1, 1]} drift={0}>
        <Take t={t} a={7.95} b={11.6} file="take-conference.mp4" from={0.4} z={[1.05, 1.18]} x={[30, -30]} />
        <Band t={t} at={8.4} out={10.15}>
          <Words t={t} size={70} weight={700} color="#fff" words={[["Cadeiras", 8.43], ["de", 8.81], ["massagem", 8.91]]} />
          <Words t={t} size={104} weight={800} color="#fff" words={[["automáticas", 9.41]]} />
        </Band>
        <Band t={t} at={10.3}>
          <Words t={t} size={70} weight={700} color="#fff" words={[["que", 10.23], ["atraem", 10.38]]} />
          <Words t={t} size={104} weight={800} color="#fff" words={[["o", 10.81], ["público", 10.91]]} />
        </Band>
      </Scene>

      {/* 5 · e conectam sua marca a conforto e bem-estar */}
      <Scene t={t} a={11.6} b={15.9} tr="zoom" bg={INK} cam={[1.0, 1.16]} drift={-60}>
        <Block t={t} top={400} at={12.0} gap={30}>
          <Words t={t} size={60} weight={600} color="#E9D9FF" words={[["e", 12.02], ["conectam", 12.12]]} />
          {(() => {
            const s = sp(t, 12.64, 12, 220);
            return <div style={{ fontFamily: PP, fontWeight: 800, fontSize: 110, color: "#fff", background: GRAD, padding: "18px 64px 28px", borderRadius: 70, whiteSpace: "nowrap",
              boxShadow: "0 30px 80px rgba(255,10,120,0.4)", opacity: Math.min(1, s * 3), transform: `scale(${0.4 + 0.6 * s})` }}>sua marca</div>;
          })()}
        </Block>
        {/* ligação da marca com os dois valores */}
        <svg width={1080} height={1920} style={{ position: "absolute", left: 0, top: 0 }}>
          <path d="M540 790 L540 910 C540 950 520 960 330 980 L330 1060" fill="none" stroke={ORANGE} strokeWidth={10} strokeLinecap="round" strokeDasharray={520} strokeDashoffset={520 * (1 - k(t, 13.3, 0.5))} />
          <path d="M540 790 L540 910 C540 950 560 960 750 980 L750 1060" fill="none" stroke={ORANGE} strokeWidth={10} strokeLinecap="round" strokeDasharray={520} strokeDashoffset={520 * (1 - k(t, 14.3, 0.5))} />
        </svg>
        {/* pontos correndo pela ligação: a marca chegando ao conforto e ao bem-estar */}
        {[[13.8, -1], [14.8, 1]].map(([at, side], j) =>
          [0, 0.33, 0.66].map((off, i) => {
            if (t < at) return null;
            const ph = ((t - at) / 0.9 + off) % 1;
            const pts = [[540, 790], [540, 910], [540 + side * 40, 960], [540 + side * 210, 980], [540 + side * 210, 1060]];
            const seg = ph * 4, n = Math.min(3, Math.floor(seg)), f = seg - n;
            const x = pts[n][0] + (pts[n + 1][0] - pts[n][0]) * f, y = pts[n][1] + (pts[n + 1][1] - pts[n][1]) * f;
            return <div key={`${j}${i}`} style={{ position: "absolute", left: x - 14, top: y - 14, width: 28, height: 28, borderRadius: 14, background: "#fff", boxShadow: `0 0 24px ${ORANGE}`, opacity: Math.sin(ph * Math.PI) }} />;
          }))}
        <div style={{ position: "absolute", left: 160, width: 340, top: 1060, display: "flex", flexDirection: "column", alignItems: "center", gap: 36 }}>
          <Circle t={t} at={13.58} size={340}><IcoChair size={190} /></Circle>
          <Words t={t} size={64} weight={800} color="#fff" words={[["conforto", 13.58]]} />
        </div>
        <div style={{ position: "absolute", left: 580, width: 340, top: 1060, display: "flex", flexDirection: "column", alignItems: "center", gap: 36 }}>
          <Circle t={t} at={14.58} size={340}><IcoHeart size={190} /></Circle>
          <Words t={t} size={64} weight={800} color="#fff" words={[["bem-estar", 14.58]]} />
        </div>
